function validate([nums1, nums2, k]) {
  for (const nums of [nums1, nums2]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50000) return 'Each array needs 1 to 5 * 10^4 values.';
    for (let i = 0; i < nums.length; i++) {
      if (!Number.isInteger(nums[i]) || nums[i] < -100000 || nums[i] > 100000) return 'Each value is a whole number from -10^5 to 10^5.';
      if (i > 0 && nums[i] < nums[i - 1]) return 'Both arrays must be sorted in non-decreasing order.';
    }
  }
  if (!Number.isInteger(k) || k < 1 || k > nums1.length * nums2.length) return 'k is between 1 and nums1.length * nums2.length.';
  return null;
}

