function kthSmallestProduct(nums1, nums2, k) {
  const countAtMost = (limit) => {
    let count = 0;
    for (const a of nums1) {
      let left = 0;
      let right = nums2.length;
      if (a >= 0) {
        while (left < right) {
          const mid = (left + right) >> 1;
          if (a * nums2[mid] <= limit) left = mid + 1;
          else right = mid;
        }
        count += left;
      } else {
        while (left < right) {
          const mid = (left + right) >> 1;
          if (a * nums2[mid] <= limit) right = mid;
          else left = mid + 1;
        }
        count += nums2.length - left;
      }
    }
    return count;
  };

  let low = -1e10;
  let high = 1e10;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (countAtMost(mid) >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

