function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const span = large ? (rand() < 0.7 ? 100000 : 50) : (rand() < 0.8 ? 6 : 100000);
  const make = () => {
    const n = large ? int(1000, 2000) : int(1, 6);
    const negShare = rand();
    const values = Array.from({ length: n }, () => {
      const roll = rand();
      if (roll < 0.1) return 0;
      const magnitude = int(1, span);
      return roll < 0.1 + 0.9 * negShare ? -magnitude : magnitude;
    });
    return values.sort((p, q) => p - q);
  };
  const nums1 = make();
  const nums2 = make();
  const total = nums1.length * nums2.length;
  const pick = rand();
  const k = pick < 0.1 ? 1 : pick < 0.2 ? total : int(1, total);
  return [nums1, nums2, k];
}
